-- ============================================================================
-- KALLICODE · 068_comentarios_modelo.sql
-- KC-DB-12-2 — COMMENT en todas las tablas, columnas y constraints del modelo v2.
--
-- La documentación del modelo (docs/modelo_datos_v2.md) se genera desde pg_catalog con db/tools/documentar_esquema.py y
-- toma el texto descriptivo de los COMMENT. Hasta ahora solo 17 de 84 tablas y 11 columnas tenían uno. Esta migración
-- completa el resto (67 tablas, 733 columnas) y describe cada constraint a partir de su propia
-- definición en el catálogo (clave primaria, unicidad, clave foránea —con la marca de si es compuesta con tenant_id— y
-- regla de dominio). Desde aquí, db/tools/documentar_esquema.py --cobertura (y su prueba en CI) falla si una tabla,
-- columna o constraint nueva llega sin COMMENT.
--
-- Cambio ADITIVO (clase A): COMMENT no altera la estructura ni los datos; el catálogo congelado
-- (db/esquema_v2.snapshot.json) no lo incluye, así que la instantánea no cambia. Solo toca los objetos que aún no
-- tienen COMMENT (re-ejecutable y sin pisar los comentarios de tickets anteriores). Sin particiones hijas: las crea
-- pg_partman con el tiempo. Sin BEGIN/COMMIT: el runner abre la transacción.
-- ============================================================================

SET LOCAL lock_timeout = '5s';
SET LOCAL ROLE kallicode_admin;

-- 1. Tablas
COMMENT ON TABLE audit.audit_events IS 'Bitácora de auditoría append-only y encadenada por tenant: cada evento lleva el sello del anterior (cadena de hashes) para detectar alteraciones. Particionada por fecha.';
COMMENT ON TABLE audit.chain_heads IS 'Cabeza de la cadena de auditoría por tenant: último sello y número de eventos, para encadenar el siguiente evento sin recorrer la bitácora.';
COMMENT ON TABLE audit.tenant_deletion_receipts IS 'Acta de eliminación de un tenant: prueba, con el tenant ya pseudonimizado (hash), de qué se borró, quién lo pidió y cuándo. Sobrevive al borrado del tenant.';
COMMENT ON TABLE cm.concepts IS 'Conceptos de dominio del grafo de CodeMapping (ontología del cliente) con su nombre en inglés y en el idioma local; capa semántica propuesta por el LLM y curable por personas.';
COMMENT ON TABLE cm.curation_queue IS 'Cola de curación humana de CodeMapping: propuestas del LLM (definiciones, conceptos, enlaces) pendientes de aprobar, corregir o rechazar.';
COMMENT ON TABLE cm.db_columns IS 'Columnas de las tablas de la base de datos del cliente, extraídas del catálogo del cliente en la fase de esquema del grafo.';
COMMENT ON TABLE cm.db_tables IS 'Tablas de la base de datos del cliente que forman parte del grafo (nodos de tipo db_table).';
COMMENT ON TABLE cm.definitions IS 'Definiciones de negocio o de módulo del grafo: descripciones consolidadas de qué hace un módulo o una regla; capa semántica generada por el LLM.';
COMMENT ON TABLE cm.doc_chunk_links IS 'Enlaces entre fragmentos de documentación (vec.doc_chunks) y nodos del grafo, con el método y la puntuación con que se estableció el vínculo.';
COMMENT ON TABLE cm.edge_types IS 'Catálogo de tipos de arista admitidos en el grafo (CALLS, DEFINES, HAS_COLUMN, REFERENCES, USES_TABLE, REALIZED_BY, RELATES, EXPRESSES) y si son dirigidas.';
COMMENT ON TABLE cm.edges IS 'Aristas del grafo de CodeMapping entre nodos de cualquier tipo; las deterministas se reconstruyen desde el repositorio y la base del cliente, las semánticas se restauran de la copia.';
COMMENT ON TABLE cm.files IS 'Archivos del repositorio del cliente ingeridos en un snapshot (nodos de tipo file), con su lenguaje y hash de contenido.';
COMMENT ON TABLE cm.incident_nodes IS 'Relación entre un incidente de producción y los nodos del grafo que afectó.';
COMMENT ON TABLE cm.node_types IS 'Catálogo de tipos de nodo del grafo (file, symbol, db_table, db_column, definition, concept) y su categoría.';
COMMENT ON TABLE cm.nodes IS 'Registro único de nodos del grafo por tenant: identificador y tipo de cada archivo, símbolo, tabla, columna, definición o concepto. Es el destino de las aristas y de los vectores.';
COMMENT ON TABLE cm.nuggets IS 'Reglas de aprendizaje (nuggets) propuestas desde incidentes y tickets, con su evidencia y su ciclo de revisión humana.';
COMMENT ON TABLE cm.repo_snapshots IS 'Cada ingesta del repositorio de un tenant: commit, rama, estado, fase de punto de control alcanzada y estadísticas por capa y por fase.';
COMMENT ON TABLE cm.snapshot_vigente IS 'Puntero por tenant al snapshot vigente del grafo; el consumidor siempre lee el snapshot al que apunta esta fila.';
COMMENT ON TABLE cm.symbols IS 'Símbolos de código extraídos por el analizador (funciones, métodos, clases, interfaces, enums, tipos, vistas y procedimientos) con su ubicación, firma y descripción.';
COMMENT ON TABLE cm.test_flow_covers IS 'Módulos del repositorio cubiertos por un flujo de prueba (relación flujo-módulo).';
COMMENT ON TABLE cm.test_flows IS 'Flujos de prueba descubiertos en el repositorio y su trazabilidad con las especificaciones y criterios de aceptación.';
COMMENT ON TABLE core.audit_exports IS 'Solicitudes de exportación de la auditoría por tenant: formato, filtros, estado y referencia al archivo generado.';
COMMENT ON TABLE core.branch_map IS 'Equivalencia por tenant entre el patrón de ramas de feature y las ramas de staging y producción donde se integra el trabajo de la fábrica.';
COMMENT ON TABLE core.connections IS 'Conexiones del tenant con sistemas externos (repositorio, mensajería, base del cliente, etc.): proveedor, configuración y referencia al secreto, nunca el secreto en claro.';
COMMENT ON TABLE core.criteria_test_traceability IS 'Trazabilidad entre un criterio de aceptación de una especificación y la ejecución de la prueba que lo verifica, con su resultado y evidencia.';
COMMENT ON TABLE core.escalations IS 'Escalaciones del pipeline a una persona: qué trabajo, etapa y paso se detuvo, por qué, con qué severidad y cómo se resolvió.';
COMMENT ON TABLE core.gate_signatures IS 'Firmas de las compuertas humanas (gates) del pipeline por ticket: acción, actor, comentario y sello que las hace verificables.';
COMMENT ON TABLE core.idempotency_keys IS 'Claves de idempotencia de la API: guardan la respuesta de una petición para devolver la misma ante un reintento con la misma clave.';
COMMENT ON TABLE core.invitations IS 'Invitaciones a unirse a un tenant con un rol; solo se guarda el hash del token.';
COMMENT ON TABLE core.job_transitions IS 'Historia de transiciones de estado de cada trabajo del pipeline, con motivo, contexto y actor.';
COMMENT ON TABLE core.jobs IS 'Trabajos del pipeline de producción: un ticket en proceso con su estado, línea de producción, prioridad y contexto de ejecución.';
COMMENT ON TABLE core.llm_steps IS 'Cada paso de LLM del pipeline: etapa, plantilla, modelo, confianza, validación, reintentos, consumo de tokens y referencias a su entrada y salida.';
COMMENT ON TABLE core.model_assignments IS 'Asignación por tenant de modelo principal y de respaldo para cada función del pipeline.';
COMMENT ON TABLE core.model_providers IS 'Proveedores de modelos configurados por tenant: referencia a la llave (no la llave), máscara, URL base y modelos disponibles.';
COMMENT ON TABLE core.notifications IS 'Notificaciones a usuarios del tenant sobre eventos de tickets.';
COMMENT ON TABLE core.onboarding_documents IS 'Documentos que el tenant sube en el onboarding para alimentar el conocimiento del proyecto: archivo, hash, estado de procesamiento y fragmentos generados.';
COMMENT ON TABLE core.organizations IS 'Organizaciones cliente (tenants) de la plataforma: raíz del aislamiento multi-tenant, a la que referencian el resto de tablas por tenant_id.';
COMMENT ON TABLE core.password_reset_tokens IS 'Tokens de restablecimiento de contraseña de un usuario; solo se guarda el hash, con vencimiento y uso único.';
COMMENT ON TABLE core.pipeline_stages IS 'Catálogo de las etapas del pipeline de producción: código, nombre, si interviene el LLM, si es terminal y su orden en el flujo.';
COMMENT ON TABLE core.plans IS 'Catálogo de planes comerciales y sus límites (líneas, LOC por mes, usuarios, almacenamiento, ayuda) y modalidades de despliegue.';
COMMENT ON TABLE core.production_lines IS 'Líneas de producción del tenant: cada línea ejecuta un trabajo a la vez (job_id) y lleva su propio estado.';
COMMENT ON TABLE core.qa_results IS 'Resultado de cada criterio de aceptación dentro de una corrida de QA, con el extracto del fallo, el veredicto visual y las evidencias.';
COMMENT ON TABLE core.qa_runs IS 'Corridas de QA de un ticket y su especificación: número de corrida y resultados de regresión y de pruebas inestables.';
COMMENT ON TABLE core.refresh_tokens IS 'Tokens de refresco de sesión de la API; solo se guarda el hash, con vencimiento, uso único y revocación.';
COMMENT ON TABLE core.schema_migrations IS 'Ledger de migraciones aplicadas: archivo, huella sha256, instante, duración y, si la migración fija una versión del esquema, su etiqueta.';
COMMENT ON TABLE core.security_findings IS 'Hallazgos de seguridad detectados sobre el código de un ticket, con regla, ubicación, severidad, veredicto y si bloquean el avance.';
COMMENT ON TABLE core.spec_alternatives IS 'Alternativas de diseño que propone una especificación, con su riesgo, la recomendada y la elegida por quien aprueba.';
COMMENT ON TABLE core.spec_criteria IS 'Criterios de aceptación de una especificación en formato dado/cuando/entonces.';
COMMENT ON TABLE core.specs IS 'Especificaciones técnicas de un ticket (versionadas): referencia al documento, alcance, plan de pruebas, migraciones propuestas y ADR en borrador.';
COMMENT ON TABLE core.subscriptions IS 'Suscripciones de un tenant a un plan, con su vigencia y renovación.';
COMMENT ON TABLE core.test_quarantine IS 'Pruebas en cuarentena por inestables, con su motivo, quién las aisló, hasta cuándo y si ya se resolvieron.';
COMMENT ON TABLE core.ticket_attachments IS 'Adjuntos de un ticket: archivo, tipo, tamaño, referencia al almacenamiento, clase y resultado del escaneo.';
COMMENT ON TABLE core.ticket_counters IS 'Contador por tenant que genera el número correlativo legible de los tickets.';
COMMENT ON TABLE core.ticket_watchers IS 'Usuarios que siguen un ticket y reciben sus notificaciones.';
COMMENT ON TABLE core.tickets IS 'Tickets de trabajo (solicitudes de cambio, errores, incidentes) del tenant, con su etapa en el pipeline, prioridad, origen y estado de las compuertas.';
COMMENT ON TABLE core.upgrade_requests IS 'Solicitudes de cambio de plan que hace un tenant.';
COMMENT ON TABLE core.usage_cycles IS 'Consumo de líneas de código (LOC) acumulado por tenant y ciclo de facturación, con el umbral alcanzado.';
COMMENT ON TABLE core.usage_loc IS 'Registro de LOC producidas por un ticket en un ciclo (añadidas, eliminadas, netas y pruebas), incluidos los ajustes manuales.';
COMMENT ON TABLE core.usage_tokens IS 'Consumo de tokens y de invocaciones de LLM por ticket, etapa y modelo, base de la medición de costo.';
COMMENT ON TABLE core.user_roles IS 'Catálogo de roles de usuario y su jerarquía.';
COMMENT ON TABLE core.users IS 'Usuarios de un tenant con su rol, estado, idioma, preferencias de notificación y último acceso; el hash de contraseña nunca sale de la base.';
COMMENT ON TABLE core.webhook_inbox IS 'Bandeja de entrada de webhooks recibidos de las conexiones del tenant, con su estado de procesamiento; garantiza la entrega única por delivery_id.';
COMMENT ON TABLE vec.acta_conversion_capa IS 'Acta de la conversión de capas de los vectores: cuántas filas se convirtieron y cuáles quedaron huérfanas, por migración.';
COMMENT ON TABLE vec.definition_embeddings IS 'Embeddings de los nodos del grafo (símbolos, definiciones y conceptos) para búsqueda semántica; referencia a cm.nodes y se borra con el nodo.';
COMMENT ON TABLE vec.doc_chunks IS 'Fragmentos de la documentación del tenant con su embedding, para búsqueda semántica sobre documentos.';
COMMENT ON TABLE vec.incident_embeddings IS 'Embedding de cada incidente de cm.incidents para encontrar incidentes parecidos.';
COMMENT ON TABLE vec.ticket_embeddings IS 'Embedding de cada ticket para detectar duplicados y tickets parecidos.';

-- 2. Columnas
COMMENT ON COLUMN audit.audit_events.id IS 'Identificador de la fila (clave primaria).';
