COMMENT ON COLUMN audit.tenant_deletion_receipts.solicitado_por IS 'Quien solicitó la eliminación.';
COMMENT ON COLUMN audit.tenant_deletion_receipts.motivo IS 'Razón de la eliminación.';
COMMENT ON COLUMN audit.tenant_deletion_receipts.filas_eliminadas IS 'Filas eliminadas por tabla, en forma de objeto JSON.';
COMMENT ON COLUMN audit.tenant_deletion_receipts.sello_acta IS 'Sello que protege el contenido del acta contra alteraciones.';
COMMENT ON COLUMN audit.tenant_deletion_receipts.ejecutado_en IS 'Instante en que se ejecutó la eliminación.';
COMMENT ON COLUMN audit.worm_exports.id IS 'Identificador de la fila (clave primaria).';
