-- 3. Constraints: el texto sale de la definición del catálogo, de modo que no puede contradecirla.
DO $$
DECLARE
    k record;
    texto text;
    cols text;
    refcols text;
    compuesta boolean;
BEGIN
    FOR k IN
        SELECT con.oid, con.conname, con.contype, con.conrelid, con.confrelid, con.conkey, con.confkey,
               con.confdeltype, con.conrelid::regclass AS tabla, con.confrelid::regclass AS destino,
               pg_get_constraintdef(con.oid) AS def
          FROM pg_constraint con
          JOIN pg_class c ON c.oid = con.conrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE n.nspname IN ('core', 'vec', 'audit', 'cm', 'public')
           AND c.relkind IN ('r', 'p')
           AND NOT c.relispartition
           AND con.conparentid = 0
           AND con.contype IN ('p', 'u', 'f', 'c', 'x', 't')
           AND NOT EXISTS (SELECT 1 FROM pg_depend d
                            WHERE d.classid = 'pg_class'::regclass AND d.objid = c.oid AND d.deptype = 'e')
           AND obj_description(con.oid, 'pg_constraint') IS NULL
         ORDER BY n.nspname, c.relname, con.conname
    LOOP
        SELECT string_agg(a.attname, ', ' ORDER BY u.ord) INTO cols
          FROM unnest(k.conkey) WITH ORDINALITY u(attnum, ord)
          JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = u.attnum;
        IF k.contype = 'p' THEN
            texto := format('Clave primaria de %s: (%s).', k.tabla, cols);
        ELSIF k.contype = 'u' THEN
            texto := format('Unicidad de (%s) en %s.', cols, k.tabla);
        ELSIF k.contype = 'f' THEN
            SELECT string_agg(a.attname, ', ' ORDER BY u.ord) INTO refcols
              FROM unnest(k.confkey) WITH ORDINALITY u(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = k.confrelid AND a.attnum = u.attnum;
            compuesta := cardinality(k.conkey) > 1 AND cols ~ '(^|, )tenant_id(,|$)';
            texto := format('Clave foránea (%s) hacia %s (%s)%s. Al borrar la fila padre: %s.',
                            cols, k.destino, refcols,
                            CASE WHEN compuesta THEN '; compuesta con tenant_id: impide referenciar filas de otro tenant' ELSE '' END,
                            CASE k.confdeltype WHEN 'a' THEN 'se rechaza (NO ACTION)' WHEN 'r' THEN 'se rechaza (RESTRICT)'
                                               WHEN 'c' THEN 'se borran en cascada las filas hijas (CASCADE)'
                                               WHEN 'n' THEN 'la columna pasa a NULL (SET NULL)'
                                               ELSE 'la columna toma su valor por defecto (SET DEFAULT)' END);
        ELSIF k.contype = 'c' THEN
            texto := format('Regla de dominio en %s: %s.', k.tabla, regexp_replace(k.def, '^CHECK \((.*)\)( NOT VALID)?$', '\1'));
        ELSIF k.contype = 't' THEN
            SELECT format('Disparador de constraint en %s: ejecuta %s al cierre de la transacción (DEFERRABLE) para verificar una regla entre filas.', k.tabla, t.tgfoid::regproc)
              INTO texto FROM pg_trigger t WHERE t.tgconstraint = k.oid;
        ELSE
            texto := format('Restricción de exclusión en %s: %s.', k.tabla, k.def);
        END IF;
        EXECUTE format('COMMENT ON CONSTRAINT %I ON %s IS %L', k.conname, k.tabla, texto);
    END LOOP;
END
$$;
